CREATE TABLE IF NOT EXISTS {schema}.settlements (id {uuid} PRIMARY KEY, kind {status} NOT NULL CHECK (kind IN ('BUY_ESCROW', 'LISTING_FEE', 'MATCH_SETTLEMENT', 'REFUND', 'FEE_REFUND')), idempotency_key {keyed} NOT NULL UNIQUE, fill_id {uuid} UNIQUE REFERENCES {schema}.fills(fill_id), order_id {uuid}, amount {numeric} NOT NULL CHECK (amount > 0), state {status} NOT NULL CHECK (state IN ('RESERVED', 'MONEY_SETTLED', 'DELIVERED', 'FAILED')), attempts {integer} NOT NULL DEFAULT 0 CHECK (attempts >= 0), last_error {body}, lease_owner {keyed}, lease_until {ts}, created_at {ts} NOT NULL{defaultNow}, updated_at {ts} NOT NULL{defaultNow}, CHECK ((lease_owner IS NULL) = (lease_until IS NULL)))
